DROP TABLE IF EXISTS `comments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `comments` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `post_id` bigint NOT NULL,
  `platform` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `comment_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `author_username` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `author_display_name` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `author_avatar_url` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `text` text COLLATE utf8mb4_unicode_ci,
  `timestamp` datetime DEFAULT NULL,
  `likes` bigint DEFAULT NULL,
  `reply_count` bigint DEFAULT NULL,
  `is_reply` tinyint DEFAULT '0',
  `parent_comment_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `scraped_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_comments_post_cid` (`post_id`,`comment_id`),
  KEY `idx_comments_post` (`post_id`),
  CONSTRAINT `fk_comments_post` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3030 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

