--
-- Table structure for table `posts`
--

DROP TABLE IF EXISTS `posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `posts` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `platform` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `post_url` varchar(700) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `post_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kind` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `account_id` bigint DEFAULT NULL,
  `author_username` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `author_display_name` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `author_is_verified` tinyint DEFAULT NULL,
  `text` text COLLATE utf8mb4_unicode_ci,
  `location_id` bigint DEFAULT NULL,
  `timestamp` datetime DEFAULT NULL,
  `likes` bigint DEFAULT NULL,
  `comments_count` bigint DEFAULT NULL,
  `shares` bigint DEFAULT NULL,
  `views` bigint DEFAULT NULL,
  `sentiment` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sentiment_score` double DEFAULT NULL,
  `entities_people` json DEFAULT NULL,
  `entities_orgs` json DEFAULT NULL,
  `entities_locations` json DEFAULT NULL,
  `topics` json DEFAULT NULL,
  `language` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `analysis_model` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `strategic_relevance` int DEFAULT NULL,
  `strategic_rationale` text COLLATE utf8mb4_unicode_ci,
  `raw_meta` json DEFAULT NULL,
  `scraped_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_posts_platform_url` (`platform`,`post_url`),
  KEY `idx_posts_platform` (`platform`),
  KEY `idx_posts_author` (`author_username`),
  KEY `idx_posts_timestamp` (`timestamp`),
  KEY `idx_posts_strategic` (`strategic_relevance`),
  KEY `fk_posts_account` (`account_id`),
  KEY `fk_posts_location` (`location_id`),
  CONSTRAINT `fk_posts_account` FOREIGN KEY (`account_id`) REFERENCES `accounts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_posts_location` FOREIGN KEY (`location_id`) REFERENCES `locations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=359 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `posts`
--

LOCK TABLES `posts` WRITE;
/*!40000 ALTER TABLE `posts` DISABLE KEYS */;
INSERT INTO `posts` VALUES (1,'facebook','https://www.facebook.com/watch/hashtag/country/',NULL,'image',NULL,'My Rol',NULL,NULL,'Countries nuclear rank 2026 #country #nuclear #ranking #viral #reels',NULL,NULL,0,0,0,NULL,'neutral',-0.5,'[]','[]','[]','[\"politics\", \"news\"]','en','llama3.2:latest',0,'The post mentions \'nuclear\' but lacks context and relevance to military or missile defense topics',NULL,'2026-07-07 07:25:22','2026-07-07 07:25:51','2026-07-09 09:37:38'),(2,'facebook',NULL,NULL,'image',NULL,'National Nuclear Security Administration',NULL,NULL,'Huge congratulations to the National Nuclear Security Administration’s 21 newly sworn-in Federal Agents! … See more',NULL,NULL,162,0,0,NULL,'neutral',-1,'[]','[\"National Nuclear Security Administration\"]','[]','[]','en','llama3.2:latest',0,'The post does not mention any of the strategic keywords (military, missile defense, naval, nuclear) and appears to be unrelated to national security or defense topics.',NULL,'2026-07-07 12:25:28','2026-07-07 07:25:51','2026-07-09 09:37:38'),(3,'facebook',NULL,NULL,'image',NULL,'World News Europe',NULL,NULL,'Ukraine has found a way to obtain nuclear weapons.And it appears that we are no longer just talking about a “technical capability.” We may be on the verge of actually … See more',NULL,NULL,206,0,0,NULL,'very_negative',-0.8,'[\"Ukraine\"]','[\"World News Europe\"]','[\"Europe\"]','[\"nuclear weapons\", \"missile defense\"]','en','llama3.2:latest',71,'The post discusses Ukraine obtaining nuclear weapons, which is a directly strategic topic related to missile defense and global security',NULL,'2026-07-07 12:25:28','2026-07-07 07:25:51','2026-07-09 09:37:39'),(4,'facebook',NULL,NULL,'image',NULL,'NUCLEAR',NULL,NULL,'Confirmado! Celebración de los 20 años de \"Heaven Denied\" en La Serena. Preventa ya disponible. Será el único show de conmemoración del álbum!!… See more',NULL,NULL,58,0,0,NULL,'neutral',-1,'[]','[]','[]','[\"music\"]','es','llama3.2:latest',0,'The post is about a music event and does not mention military, missile defense, naval, or nuclear topics at all.',NULL,'2026-07-07 12:25:28','2026-07-07 07:25:51','2026-07-09 09:37:40'),(5,'facebook',NULL,NULL,'image',NULL,'NUCLEAR',NULL,NULL,'El 1 de julio de 2010 lanzamos Jehovirus, un disco que nos definió y nos llevó más allá de nuestras fronteras. Fue pura energía y brutalidad, y gracias a él tuvimos la … See more',NULL,NULL,117,0,0,NULL,'neutral',-1,'[]','[]','[]','[\"music\"]','es','llama3.2:latest',0,'The post is unrelated to military, missile defense, naval, or nuclear topics and appears to be a personal reflection on a music album.',NULL,'2026-07-07 07:25:29','2026-07-07 07:25:51','2026-07-09 09:37:40'),(6,'facebook',NULL,NULL,'image',NULL,'Huzaifa Rehman',NULL,NULL,'Youm-e-Takbeer is observed in Pakistan on 28 May to commemorate the successful nuclear tests conducted in Chagai, Balochistan, in 1998. The day symbolizes Pakistan’s de… See more',NULL,NULL,124,0,0,NULL,'neutral',-0.2,'[]','[]','[\"Pakistan\", \"Chagai\", \"Balochistan\"]','[\"nuclear tests\", \"Pakistan\'s national day\"]','en','llama3.2:latest',46,'The post mentions nuclear tests, but only in a historical context and without discussing military capabilities or missile defense',NULL,'2026-07-07 12:26:14','2026-07-07 07:26:39','2026-07-09 09:41:00'),(7,'facebook',NULL,NULL,'image',NULL,'Connected Pakistan',NULL,NULL,'Pakistan has reportedly unveiled the Fatah 3 supers0nic cru!se m!s-sile, marking what analysts describe as a significant development in the country’s indigenous defense… See more',NULL,NULL,161,0,0,NULL,'neutral',0.8,'[]','[\"Connected Pakistan\"]','[\"Pakistan\"]','[\"missile defense\", \"naval\", \"nuclear\"]','en','llama3.2:latest',71,'The post discusses Pakistan\'s indigenous defense capabilities and a new missile system, indicating a strategic development in the country\'s military sector.',NULL,'2026-07-07 12:26:14','2026-07-07 07:26:39','2026-07-09 09:41:01'),(8,'facebook',NULL,NULL,'ima